/* Similar: styling a flex container */
.container {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
}

/* Example: fixed dimensions for a container */
.box {
    width: 300px;
    height: 200px;
}

/* Example: making an element fill its parent */
img {
    width: 100%;
    height: 100%;
}

/* Similar: applying a CSS property */
img {
    object-fit: fill;
}

